#!/usr/bin/env node
/**
 * Builds the SQL migration that stores the demo scenario (tools/demo-data, generated by
 * generate-mock-data.mjs) as a template inside the database. `public.seed_demo_data()` copies the
 * template into the caller's organization with fresh ids and dates shifted so that the scenario's
 * reference day becomes "today".
 *
 *   node tools/build-demo-seed.mjs <output.sql>
 *
 * Rows are converted to the table's snake_case columns here; ids stay as the generator's text ids
 * and are mapped to new uuids at seed time.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const DATA = join(dirname(fileURLToPath(import.meta.url)), 'demo-data');
const REFERENCE_DATE = '2026-10-24'; // TODAY in generate-mock-data.mjs
const read = (name) => JSON.parse(readFileSync(join(DATA, `${name}.json`), 'utf8'));
const snake = (key) => key.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();

/** camelCase record → snake_case row; Money fields split into _amount / _currency. */
function toRow(record, { money = [], drop = [] } = {}) {
  const row = {};
  for (const [key, value] of Object.entries(record)) {
    if (drop.includes(key) || key === 'organizationId') continue;
    if (money.includes(key)) {
      row[`${snake(key)}_amount`] = value?.amount ?? 0;
      row[`${snake(key)}_currency`] = value?.currency ?? 'MZN';
      continue;
    }
    row[snake(key)] = value;
  }
  return row;
}

const users = read('users');
const owner = users.find((u) => u.role === 'owner');
const vehicles = read('vehicles');
const drivers = read('drivers');
const trips = read('trips');

/**
 * Insert order matters (foreign keys). `ids`: columns holding generator ids (mapped to uuids);
 * `dates` / `timestamps`: shifted by the number of days between REFERENCE_DATE and today.
 */
const entities = [
  {
    table: 'routes',
    rows: read('routes').map((r) => toRow(r)),
    ids: ['id'],
  },
  {
    table: 'customers',
    rows: read('customers').map((c) => toRow(c, { money: ['creditLimit', 'outstandingBalance'] })),
    ids: ['id'],
    timestamps: ['created_at', 'updated_at'],
  },
  {
    // The generator's owner becomes the signed-in user (not inserted); everyone else is a member
    // without a login account.
    table: 'organization_members',
    rows: users.filter((u) => u.id !== owner.id).map((u) => toRow(u)),
    ids: ['id'],
    timestamps: ['last_active_at', 'invited_at', 'created_at'],
  },
  {
    // Links to drivers / trailers are set afterwards (see seed_demo_data), when those rows exist.
    table: 'vehicles',
    rows: vehicles.map((v) => toRow(v, { drop: ['statusHistory', 'assignedDriverId', 'linkedTrailerId'] })),
    ids: ['id'],
    dates: ['acquisition_date'],
    timestamps: ['created_at', 'updated_at'],
  },
  {
    table: 'vehicle_status_changes',
    rows: vehicles.flatMap((v) =>
      v.statusHistory.map((h) => ({ vehicle_id: v.id, changed_on: h.date, from_status: h.from, to_status: h.to, reason: h.reason })),
    ),
    ids: ['vehicle_id'],
    dates: ['changed_on'],
  },
  {
    table: 'drivers',
    rows: drivers.map((d) => toRow(d)),
    ids: ['id', 'assigned_vehicle_id'],
    dates: ['licence_expiry', 'hire_date'],
    timestamps: ['created_at', 'updated_at'],
  },
  {
    table: 'trailers',
    rows: read('trailers').map((t) => toRow(t)),
    ids: ['id', 'assigned_vehicle_id'],
    dates: ['last_inspection_date', 'inspection_expiry'],
    timestamps: ['created_at', 'updated_at'],
  },
  {
    table: 'trips',
    rows: trips.map((t) => toRow(t, { money: ['revenue'], drop: ['timeline'] })),
    ids: ['id', 'customer_id', 'vehicle_id', 'driver_id', 'trailer_id', 'route_id'],
    timestamps: ['planned_departure', 'planned_arrival', 'actual_departure', 'actual_arrival', 'created_at', 'updated_at'],
  },
  {
    table: 'trip_events',
    rows: trips.flatMap((t) =>
      t.timeline.map((e) => ({ trip_id: t.id, occurred_at: e.timestamp, type: e.type, status: e.status, location: e.location, note: e.note })),
    ),
    ids: ['trip_id'],
    timestamps: ['occurred_at'],
  },
  {
    table: 'fuel_records',
    rows: read('fuel-records').map((f) => toRow(f, { money: ['pricePerLitre', 'totalAmount'] })),
    ids: ['id', 'vehicle_id', 'driver_id', 'trip_id'],
    timestamps: ['timestamp', 'created_at', 'updated_at'],
  },
  {
    table: 'expenses',
    rows: read('expenses').map((e) => toRow(e, { money: ['amount'] })),
    ids: ['id', 'vehicle_id', 'trip_id', 'driver_id', 'submitted_by_user_id'],
    dates: ['date'],
    timestamps: ['created_at', 'updated_at'],
  },
  {
    table: 'maintenance_records',
    rows: read('maintenance-records').map((m) => toRow(m)),
    ids: ['id', 'vehicle_id'],
    dates: ['planned_date', 'started_date', 'completed_date', 'next_service_date'],
    timestamps: ['created_at', 'updated_at'],
  },
  {
    // Demo documents carry no stored file (a "download" would have nothing to open).
    table: 'documents',
    rows: read('documents').map((d) => ({ ...toRow(d), file_name: null, file_size_kb: null })),
    ids: ['id', 'entity_id'],
    dates: ['issue_date', 'expiry_date'],
    timestamps: ['created_at', 'updated_at'],
  },
];

// Vehicle → driver / trailer links, applied after both exist.
const vehicleLinks = vehicles
  .filter((v) => v.assignedDriverId || v.linkedTrailerId)
  .map((v) => ({ id: v.id, assigned_driver_id: v.assignedDriverId, linked_trailer_id: v.linkedTrailerId }));

/** Columns inserted for a table: every key present in its rows. */
const columnsOf = (rows) => [...new Set(rows.flatMap((row) => Object.keys(row)))];

const dollar = (value) => {
  const json = JSON.stringify(value);
  if (json.includes('$demo$')) throw new Error('Template contains the dollar-quote tag');
  return `$demo$${json}$demo$::jsonb`;
};
const textArray = (values) => `array[${values.map((v) => `'${v}'`).join(', ')}]::text[]`;

const out = process.argv[2];
if (!out) throw new Error('Usage: node tools/build-demo-seed.mjs <output.sql>');

const sql = `-- FleetOps MZ — demo data template and seed_demo_data().
-- GENERATED by tools/build-demo-seed.mjs from tools/demo-data (do not edit by hand; regenerate and add
-- a new migration instead). All companies, people, plates and amounts are fictional.

create table if not exists private.demo_template (
  position   integer primary key,
  entity     text not null unique,
  columns    text[] not null,
  id_keys    text[] not null default '{}',
  date_keys  text[] not null default '{}',
  ts_keys    text[] not null default '{}',
  rows       jsonb not null
);
create table if not exists private.demo_settings (
  key   text primary key,
  value jsonb not null
);
truncate private.demo_template;
truncate private.demo_settings;

insert into private.demo_settings (key, value) values
  ('reference_date', '"${REFERENCE_DATE}"'),
  ('owner_id', '"${owner.id}"'),
  ('vehicle_links', ${dollar(vehicleLinks)});

insert into private.demo_template (position, entity, columns, id_keys, date_keys, ts_keys, rows) values
${entities
  .map(
    (e, i) =>
      `  (${i + 1}, '${e.table}', ${textArray(['organization_id', ...columnsOf(e.rows)])}, ${textArray(e.ids ?? [])}, ${textArray(e.dates ?? [])}, ${textArray(e.timestamps ?? [])},\n   ${dollar(e.rows)})`,
  )
  .join(',\n')};

-- Maps one template row to the organization: generator ids → uuids (temp table demo_ids), dates and
-- timestamps shifted by p_offset days.
create or replace function private.demo_row(p_row jsonb, p_org uuid, p_offset integer, p_ids text[], p_dates text[], p_ts text[])
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
  v_row jsonb := p_row || jsonb_build_object('organization_id', p_org);
  v_key text;
begin
  foreach v_key in array p_ids loop
    if v_row ? v_key and jsonb_typeof(v_row -> v_key) = 'string' then
      v_row := jsonb_set(v_row, array[v_key], coalesce(to_jsonb((select d.new_id from demo_ids d where d.old_id = v_row ->> v_key)), 'null'::jsonb));
    end if;
  end loop;
  foreach v_key in array p_dates loop
    if v_row ? v_key and jsonb_typeof(v_row -> v_key) = 'string' then
      v_row := jsonb_set(v_row, array[v_key], to_jsonb(((v_row ->> v_key)::date + p_offset)::text));
    end if;
  end loop;
  foreach v_key in array p_ts loop
    if v_row ? v_key and jsonb_typeof(v_row -> v_key) = 'string' then
      v_row := jsonb_set(v_row, array[v_key], to_jsonb((v_row ->> v_key)::timestamptz + make_interval(days => p_offset)));
    end if;
  end loop;
  return v_row;
end;
$$;
revoke all on function private.demo_row(jsonb, uuid, integer, text[], text[], text[]) from public;

-- Fills the caller's organization with the demo scenario. Owner / admin only, and only while the
-- organization has no operational data (so it never mixes with or duplicates real records).
create or replace function public.seed_demo_data()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org     uuid;
  v_member  uuid;
  v_today   date;
  v_offset  integer;
  v_entity  private.demo_template;
  v_total   integer := 0;
  v_count   integer;
begin
  select m.organization_id, m.id into v_org, v_member
  from public.organization_members m
  where m.user_id = (select auth.uid()) and m.status = 'active' and m.role in ('owner', 'admin')
  order by m.created_at
  limit 1;
  if v_org is null then
    raise exception 'only an owner or admin can load demo data' using errcode = '42501';
  end if;
  if exists (select 1 from public.vehicles where organization_id = v_org)
     or exists (select 1 from public.drivers where organization_id = v_org)
     or exists (select 1 from public.customers where organization_id = v_org)
     or exists (select 1 from public.trips where organization_id = v_org) then
    raise exception 'demo data can only be loaded into an organization without data' using errcode = 'P0001';
  end if;

  select (now() at time zone o.time_zone)::date into v_today from public.organizations o where o.id = v_org;
  v_offset := v_today - (select (value #>> '{}')::date from private.demo_settings where key = 'reference_date');

  -- Generator ids → fresh uuids; the generator's owner is the caller.
  create temp table demo_ids (old_id text primary key, new_id uuid not null) on commit drop;
  insert into demo_ids (old_id, new_id)
  select distinct r ->> 'id', gen_random_uuid()
  from private.demo_template t, jsonb_array_elements(t.rows) r
  where r ? 'id';
  insert into demo_ids (old_id, new_id)
  values ((select value #>> '{}' from private.demo_settings where key = 'owner_id'), v_member)
  on conflict (old_id) do update set new_id = excluded.new_id;

  for v_entity in select * from private.demo_template order by position loop
    execute format(
      'insert into public.%I (%s) select %s from jsonb_populate_recordset(null::public.%I, $1)',
      v_entity.entity,
      (select string_agg(quote_ident(c), ', ') from unnest(v_entity.columns) c),
      (select string_agg(quote_ident(c), ', ') from unnest(v_entity.columns) c),
      v_entity.entity
    )
    using (
      select coalesce(jsonb_agg(private.demo_row(r, v_org, v_offset, v_entity.id_keys, v_entity.date_keys, v_entity.ts_keys)), '[]'::jsonb)
      from jsonb_array_elements(v_entity.rows) r
    );
    get diagnostics v_count = row_count;
    v_total := v_total + v_count;
  end loop;

  -- Vehicle → driver / trailer links.
  update public.vehicles v
     set assigned_driver_id = (select d.new_id from demo_ids d where d.old_id = l ->> 'assigned_driver_id'),
         linked_trailer_id  = (select d.new_id from demo_ids d where d.old_id = l ->> 'linked_trailer_id')
    from jsonb_array_elements((select value from private.demo_settings where key = 'vehicle_links')) l
   where v.id = (select d.new_id from demo_ids d where d.old_id = l ->> 'id');

  -- Driver incidents (jsonb): shift dates and point trip links to the new trips.
  update public.drivers dr
     set incidents = coalesce((
       select jsonb_agg(i || jsonb_build_object(
                'date', ((i ->> 'date')::date + v_offset)::text,
                'tripId', (select d.new_id from demo_ids d where d.old_id = i ->> 'tripId')))
       from jsonb_array_elements(dr.incidents) i), '[]'::jsonb)
   where dr.organization_id = v_org and jsonb_array_length(dr.incidents) > 0;

  perform private.generate_notifications(v_org);
  return v_total;
end;
$$;
revoke all on function public.seed_demo_data() from public, anon;
grant execute on function public.seed_demo_data() to authenticated;
`;

writeFileSync(out, sql);
console.log(`Wrote ${out} (${(sql.length / 1024).toFixed(0)} KB, ${entities.reduce((n, e) => n + e.rows.length, 0)} template rows)`);
